def sub(text, pattern, repl, flags=0): return re.sub(pattern,repl,text,flags=flags)
def update_page(path,d):
    text=path.read_text(encoding='utf-8');h=d['h'];p=d.get('p')
    text=sub(text,r'(<div class="asof">)Updated [^<]+',r'\1Updated '+UPDATED)
    text=sub(text,r'(Snapshot · )[A-Za-z]+\. \d{1,2}, 2026',r'\1'+UPDATED)
    text=sub(text,r'HotB · <span data-hit="PA">\d+</span> PA',f'HotB · <span data-hit="PA">{h["PA"]}</span> PA')
    text=sub(text,r'(data-metric="decision"[^>]*>.*?<strong>)[^<]*(</strong>)',lambda m:m.group(1)+h['decisionPct']+m.group(2),re.S)
    text=sub(text,r'(data-metric="aba"[^>]*>.*?<strong><span[^>]*>)1P [^<]+<br>2K [^<]+(</span></strong>)',lambda m:m.group(1)+f'1P {h["firstPct"]}<br>2K {h["twoPct"]}'+m.group(2),re.S)
    text=sub(text,r'(data-metric="hhb"[^>]*>.*?<strong>)[^<]*(</strong>)',lambda m:m.group(1)+h['HHBpct']+m.group(2),re.S)
    for label,key in [('AVG','AVG'),('OBP','OBP'),('K%','Kpct')]: text=sub(text,rf'(<span[^>]*>{re.escape(label)}</span><strong>)[^<]*(</strong>)',lambda m,k=key:m.group(1)+h[k]+m.group(2))
    if p:
        for label,key in [('IP','IP'),('ERA','ERA'),('WHIP','WHIP'),('K/BB','KBB'),('OBA','OBA'),('STRIKE %','StrikePct')]: text=sub(text,rf'(<span[^>]*>{re.escape(label)}</span><strong(?: data-pitch="{re.escape(label)}")?>)[^<]*(</strong>)',lambda m,k=key:m.group(1)+p[k]+m.group(2),1)
    text=sub(text,r'<p class="data-note">.*?</p>',f'<p class="data-note">Hitting metrics are calculated from {d["name"]}’s saved pitch-by-pitch HotB game data through Oct. 18, 2026.</p>',re.S)
    text=sub(text,r'(<div class="pc-decision-summary"><b>)[^<]+(</b><span>)\d+( scored decisions</span>)',lambda m:m.group(1)+h['decisionPct']+m.group(2)+str(h['decisionN'])+m.group(3))
    dc=h['decisionCounts'];text=sub(text,r"box\(\[\['Good',\d+\],\['Minor Poor',\d+\],\['Poor',\d+\],\['Not Scored',\d+\]\]\)",f"box([['Good',{dc['GOOD']}],['Minor Poor',{dc['MINOR']}],['Poor',{dc['POOR']}],['Not Scored',{dc['NOT_SCORED']}]])")
    text=sub(text,r'(<div class="pc-aba-summary"><div><b>)[^<]+(</b><span>1ST PITCH APPROACH</span></div><div><b>)[^<]+(</b><span>2-STRIKE APPROACH</span>)',lambda m:m.group(1)+h['firstPct']+m.group(2)+h['twoPct']+m.group(3))
    fc,tc=h['firstCounts'],h['twoCounts'];boxes=list(re.finditer(r"box\(\[\['GOOD',\d+\],\['MINOR',\d+\],\['POOR',\d+\]\]\)",text))
    for m,v in reversed(list(zip(boxes[:2],[fc,tc]))): text=text[:m.start()]+f"box([['GOOD',{v['GOOD']}],['MINOR',{v['MINOR']}],['POOR',{v['POOR']}]])"+text[m.end():]
    text=sub(text,r'1P: \d+ scored first pitches · 2K: \d+ plate appearances that reached two strikes',f'1P: {h["firstN"]} scored first pitches · 2K: {h["twoN"]} plate appearances that reached two strikes')
    weak=round(h['WEAK']/h['battedBalls']*100) if h['battedBalls'] else 0
    text=sub(text,r"\[\['HHB%','[^']*'\],\['WEAK%','[^']*'\],\['AVG ON HHB','[^']*'\],\['AVG ON WEAK','[^']*'\]\]",f"[['HHB%','{h['HHBpct']}'],['WEAK%','{weak}%'],['AVG ON HHB','{h['avgOnHHB']}'],['AVG ON WEAK','{h['avgOnWeak']}']]")
    text=text.replace('October 16, 2026 HotB backup.','October 18, 2026 HotB backup.').replace('through October 10, 2026.','through October 18, 2026.')
    path.write_text(text,encoding='utf-8')
for slug,d in PLAYERS.items(): update_page(Path(slug)/'index.html',d)
